import { useState, useEffect } from "react";
import axios from "axios";

function Dashboard() {
  const [data, setData] = useState({
    user: { full_name: "", email: "" },
    wishlist: [],
    recentActivity: [],
  });
  const [loading, setLoading] = useState(true);
  const userId = localStorage.getItem("userId");

  useEffect(() => {
    if (!userId) {
      window.location.href = "/login";
      return;
    }

    const fetchDashboardData = async () => {
      try {
        const res = await axios.get("http://localhost:5000/dashboard", {
          headers: { "user-id": userId },
        });
        setData(res.data);
      } catch (error) {
        console.error("Error fetching dashboard data:", error);
      } finally {
        setLoading(false);
      }
    };
    fetchDashboardData();
  }, [userId]);

  if (loading) return <div className="text-center text-white">Loading...</div>;

  return (
    <div className="min-h-screen bg-gray-100 p-6">
      <h1 className="text-3xl font-bold text-center mb-6 text-gray-800">
        My Dashboard
      </h1>
      <div className="bg-white rounded-lg shadow-lg p-6">
        {/* User Details */}
        <div className="mb-6">
          <h2 className="text-xl font-semibold">
            Welcome, {data.user.full_name}
          </h2>
          <p className="text-gray-600">Email: {data.user.email}</p>
        </div>

        {/* Wishlist */}
        <div className="mb-6">
          <h2 className="text-xl font-semibold">My Wishlist</h2>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            {data.wishlist.length > 0 ? (
              data.wishlist.map((home) => (
                <div key={home.id} className="bg-gray-100 p-2 rounded">
                  <img
                    src={
                      home.images.length > 0
                        ? `http://localhost:5000${home.images[0]}`
                        : "http://localhost:5000/house_placeholder.jpg"
                    }
                    alt="Wishlist Property"
                    className="w-full h-20 object-cover rounded"
                  />
                  <p className="text-sm">{home.address}</p>
                  <p className="text-sm">₹{home.price}/night</p>
                </div>
              ))
            ) : (
              <p className="text-gray-600">No items in your wishlist.</p>
            )}
          </div>
        </div>

        {/* Recent Activity */}
        <div>
          <h2 className="text-xl font-semibold">Recent Activity</h2>
          {data.recentActivity.length > 0 ? (
            <ul className="list-disc pl-5">
              {data.recentActivity.map((activity, i) => (
                <li key={i} className="text-gray-600">
                  Booked: {activity.address} for ₹{activity.price}
                </li>
              ))}
            </ul>
          ) : (
            <p className="text-gray-600">No recent activity.</p>
          )}
        </div>
      </div>
    </div>
  );
}

export default Dashboard;
